INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000012d',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss nature and wilderness","Use Natur vocabulary at B1","Talk about Germany''s natural landscapes"],"explanation":{"intro":"Nature vocabulary at B1 covers Germany''s diverse landscapes and natural environments.","culturalNote":"Germany has significant natural areas: Schwarzwald (Black Forest), Bayerischer Wald (Bavarian Forest — first German national park), Berchtesgaden Alps, Rügen island, Lüneburger Heide. About 30% of Germany is forest. German Romantik revered nature — Caspar David Friedrich painted iconic German landscapes."},"examples":[{"german":"Der Schwarzwald ist bekannt für seine dichten Fichtenwälder und idyllischen Täler.","english":"The Black Forest is known for its dense spruce forests and idyllic valleys."},{"german":"Naturschutzgebiete schützen seltene Tier- und Pflanzenarten.","english":"Nature reserves protect rare animal and plant species."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss Germany''s natural landscapes and nature conservation."}}',
'{"items":[{"word":"dicht","translation":"dense/thick","pronunciation":"dikht","example":"Dichter Wald."},{"word":"idyllisch","translation":"idyllic","pronunciation":"ee-DÜL-ish","example":"Idyllische Landschaft."},{"word":"das Naturschutzgebiet","translation":"nature reserve","pronunciation":"dahs nah-TOOR-shoots-geh-beet","example":"Ein Naturschutzgebiet."},{"word":"die Pflanzenart","translation":"plant species","pronunciation":"dee PFLAN-tsen-art","example":"Seltene Pflanzenarten."},{"word":"das Tal","translation":"valley","pronunciation":"dahs TAHL","example":"Das Tal erkunden."},{"word":"überwältigen","translation":"to overwhelm","pronunciation":"ü-ber-VEL-tee-gen","example":"Überwältigende Natur."}]}',
'{"title":"Bekannt für — known for","pattern":"jemand/etwas ist bekannt für + accusative (to be known for something)","explanation":"Bekannt für + accusative = known for. Der Schwarzwald ist bekannt für seine Wälder = The Black Forest is known for its forests. Also: bekannt als (known as — an identity): Er ist bekannt als Experte = He is known as an expert. Sich bekannt machen (to make oneself known). Die Bekanntheit (renown, fame). Weltbekannt (world-famous — compound adjective).","examples":[{"sentence":"München ist bekannt für das Oktoberfest und Bier.","translation":"Munich is known for the Oktoberfest and beer."},{"sentence":"Deutschland ist bekannt für seine Ingenieurskunst.","translation":"Germany is known for its engineering."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Idyllisch'' means?","options":["idyllic","peaceful","quiet","beautiful"],"correctAnswer":"idyllic"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The Black Forest is known for its dense spruce forests and idyllic valleys.","options":["Der Schwarzwald ist bekannt für seine dichten Fichtenwälder und idyllischen Täler.","Der Schwarzwald hat viele Wälder.","Der Schwarzwald ist schön.","Fichtenwälder sind im Schwarzwald."],"correctAnswer":"Der Schwarzwald ist bekannt für seine dichten Fichtenwälder und idyllischen Täler."},{"id":"ex3","type":"FILL_IN_BLANK","question":"München ist bekannt ___ das Oktoberfest und Bier.","options":["für","als","durch","wegen"],"correctAnswer":"für"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Germany is known for its engineering","wordBankItems":["Deutschland","ist","bekannt","für","seine","Ingenieurskunst","."],"correctAnswer":"Deutschland ist bekannt für seine Ingenieurskunst ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Dicht'' in ''dichter Wald'' means?","options":["dense/thick","dark","deep","impenetrable"],"correctAnswer":"dense/thick"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000012e',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss animals in Germany","Use Tier vocabulary at B1","Talk about wildlife and nature conservation"],"explanation":{"intro":"Wildlife vocabulary at B1 covers animals native to Germany and conservation efforts.","culturalNote":"Germany has diverse wildlife: Wölfe (wolves — reintroduced), Luchse (lynx), Wildschweine (wild boar — common, even in cities), Biber (beaver — returned), Seeadler (white-tailed eagle). Artenschutz (species protection) is taken seriously. The NABU (nature protection association) is active."},"examples":[{"german":"Der Wolf wurde in Deutschland nach Jahrzehnten erfolgreich wiederangesiedelt.","english":"The wolf was successfully reintroduced in Germany after decades."},{"german":"Wildschweine sind inzwischen auch in vielen Städten anzutreffen.","english":"Wild boar are now to be found even in many cities."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss German wildlife and animal conservation."}}',
'{"items":[{"word":"wiederansiedeln","translation":"to reintroduce/resettle","pronunciation":"VEE-der-an-zee-deln","example":"Wölfe wiederansiedeln."},{"word":"anzutreffen","translation":"to be found/encountered","pronunciation":"AN-tsoo-tref-en","example":"Anzutreffen sein."},{"word":"der Artenschutz","translation":"species protection","pronunciation":"dayr AR-ten-shoots","example":"Artenschutz betreiben."},{"word":"das Wildschwein","translation":"wild boar","pronunciation":"dahs VILT-shvyn","example":"Das Wildschwein."},{"word":"bedroht","translation":"threatened/endangered","pronunciation":"beh-DROHT","example":"Bedrohte Arten."},{"word":"der Lebensraum","translation":"habitat","pronunciation":"dayr LAY-bens-rowm","example":"Lebensraum schützen."}]}',
'{"title":"Wiederansiedeln — to reintroduce (species) / resettle","pattern":"etwas/jemanden wiederansiedeln (separable) — to reintroduce/resettle","explanation":"Wiederansiedeln (separable) = to reintroduce (animals), resettle (people). Der Wolf wurde wiederangesiedelt = The wolf was reintroduced. Passive very common in conservation language. Related: ansiedeln (to settle, establish — without wieder), die Ansiedlung (settlement/establishment), die Wiederansiedlung (reintroduction). Also: aussetzen = to release (animal) — more casual term for releasing individual animals.","examples":[{"sentence":"Der Luchs wurde in verschiedenen deutschen Wäldern wiederangesiedelt.","translation":"The lynx was reintroduced in various German forests."},{"sentence":"Die Ansiedlung von Bibern hat die Flusslandschaften verändert.","translation":"The settlement of beavers has changed the river landscapes."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Bedroht'' means?","options":["threatened/endangered","at risk","vulnerable","protected"],"correctAnswer":"threatened/endangered"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The wolf was successfully reintroduced in Germany after decades.","options":["Der Wolf wurde in Deutschland nach Jahrzehnten erfolgreich wiederangesiedelt.","Wölfe leben wieder in Deutschland.","Der Wolf ist zurück in Deutschland.","Deutschland hat wieder Wölfe."],"correctAnswer":"Der Wolf wurde in Deutschland nach Jahrzehnten erfolgreich wiederangesiedelt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Der Luchs wurde in verschiedenen deutschen Wäldern ___.","options":["wiederangesiedelt","wiederansiedeln","angesiedelt","wieder angesiedelt"],"correctAnswer":"wiederangesiedelt"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The settlement of beavers has changed the river landscapes","wordBankItems":["Die","Ansiedlung","von","Bibern","hat","die","Flusslandschaften","verändert","."],"correctAnswer":"Die Ansiedlung von Bibern hat die Flusslandschaften verändert ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Der Lebensraum'' means?","options":["habitat","living space","biotope","territory"],"correctAnswer":"habitat"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000012f',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss ecosystems","Use Ökosystem vocabulary","Talk about natural cycles and ecological balance"],"explanation":{"intro":"Ecosystem vocabulary at B1 covers ecological concepts, food chains, and natural cycles.","culturalNote":"Germany''s ecological awareness is strong. Concepts like Ökosystem, Nahrungskette (food chain), and Kreislauf (cycle) are taught in schools and widely understood. Environmental education (Umweltbildung) is part of the curriculum. The Wald (forest) is both an ecological and cultural symbol."},"examples":[{"german":"Jedes Tier hat eine wichtige Funktion im Ökosystem.","english":"Every animal has an important function in the ecosystem."},{"german":"Wenn eine Art ausstirbt, kann das das gesamte Ökosystem destabilisieren.","english":"When a species becomes extinct, it can destabilise the entire ecosystem."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss ecosystems, food chains, and ecological concepts in German."}}',
'{"items":[{"word":"die Nahrungskette","translation":"food chain","pronunciation":"dee NAH-roongs-ket-eh","example":"Die Nahrungskette."},{"word":"aussterben","translation":"to become extinct","pronunciation":"OWS-ster-ben","example":"Arten sterben aus."},{"word":"destabilisieren","translation":"to destabilise","pronunciation":"des-tah-bee-lee-ZEER-en","example":"Das System destabilisieren."},{"word":"gesamte","translation":"entire/whole","pronunciation":"geh-ZAM-teh","example":"Das gesamte Ökosystem."},{"word":"der Kreislauf","translation":"cycle/circuit","pronunciation":"dayr KRYS-lowf","example":"Der natürliche Kreislauf."},{"word":"die Biodiversität","translation":"biodiversity","pronunciation":"dee bee-oh-dee-ver-zee-TÄT","example":"Biodiversität erhalten."}]}',
'{"title":"Aussterben — to become extinct (separable)","pattern":"etwas stirbt aus (separable) — to become extinct, die out","explanation":"Aussterben (separable, intransitive, sein): ausgestorben (extinct, past), stirbt aus (becoming extinct). Die Art stirbt aus = The species is dying out. Ausgestorben = extinct. Vom Aussterben bedroht = threatened with extinction. Related: bedroht (threatened), gefährdet (endangered — milder). Note: this is a natural process verb — for companies: eingehen (a company dies, collapses).","examples":[{"sentence":"Viele Insektenarten sterben aufgrund von Pestiziden aus.","translation":"Many insect species are dying out due to pesticides."},{"sentence":"Diese Tierart ist seit dem 18. Jahrhundert ausgestorben.","translation":"This animal species has been extinct since the 18th century."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Biodiversität'' means?","options":["biodiversity","biological diversity","ecological richness","species variety"],"correctAnswer":"biodiversity"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"When a species becomes extinct, it can destabilise the entire ecosystem.","options":["Wenn eine Art ausstirbt, kann das das gesamte Ökosystem destabilisieren.","Ausgestorbene Arten fehlen im System.","Das Ökosystem braucht alle Arten.","Arten sterben aus und das ist schlecht."],"correctAnswer":"Wenn eine Art ausstirbt, kann das das gesamte Ökosystem destabilisieren."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Viele Insektenarten ___ aufgrund von Pestiziden aus.","options":["sterben","sterben ... aus","aussterben","ausgestorben"],"correctAnswer":"sterben ... aus"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: This animal species has been extinct since the 18th century","wordBankItems":["Diese","Tierart","ist","seit","dem","18.","Jahrhundert","ausgestorben","."],"correctAnswer":"Diese Tierart ist seit dem 18. Jahrhundert ausgestorben ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Vom Aussterben bedroht'' means?","options":["threatened with extinction","endangered","at risk","near extinct"],"correctAnswer":"threatened with extinction"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000130',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss weather and climate at B1","Use advanced Wetter vocabulary","Talk about climate change impacts"],"explanation":{"intro":"Advanced weather and climate vocabulary at B1 covers climate science, forecasting, and climate change.","culturalNote":"Germany''s climate is transitioning noticeably — hotter summers (Hitzewellen), flooding (Hochwasser), drought (Dürre) are more frequent. The term Klimakatastrophe (climate catastrophe) is increasingly common in German media. The DWD (Deutscher Wetterdienst) is the national weather service."},"examples":[{"german":"Der Klimawandel führt dazu, dass Extremwetterereignisse häufiger auftreten.","english":"Climate change is causing extreme weather events to occur more frequently."},{"german":"Die durchschnittliche Jahrestemperatur in Deutschland ist um 1,6 Grad gestiegen.","english":"The average annual temperature in Germany has risen by 1.6 degrees."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss climate change, weather patterns, and meteorology in German."}}',
'{"items":[{"word":"durchschnittlich","translation":"average/on average","pronunciation":"DOORKH-shnit-likh","example":"Durchschnittliche Temperatur."},{"word":"die Jahrestemperatur","translation":"annual temperature","pronunciation":"dee YAH-res-tem-peh-rah-toor","example":"Die Jahrestemperatur."},{"word":"auftreten","translation":"to occur/appear","pronunciation":"OWF-tray-ten","example":"Häufiger auftreten."},{"word":"die Dürre","translation":"drought","pronunciation":"dee DÜR-reh","example":"Eine Dürre."},{"word":"das Hochwasser","translation":"flood/high water","pronunciation":"dahs HOKH-vas-er","example":"Hochwasser droht."},{"word":"die Hitzewelle","translation":"heat wave","pronunciation":"dee HIT-seh-vel-eh","example":"Eine Hitzewelle."}]}',
'{"title":"Dazu führen dass — to cause/lead to that","pattern":"etwas führt dazu, dass + clause (something causes/leads to a result)","explanation":"Führen zu + dative (direct noun): Das führt zu Problemen = That leads to problems. Führen dazu, dass + clause (before a full clause): Das führt dazu, dass es häufiger regnet = That leads to it raining more often. The dazu serves as anticipatory pronoun for the dass clause. Very common in scientific/causal language. Compare: verursachen dass (to cause that — more direct causation).","examples":[{"sentence":"Das führt dazu, dass weniger Grundwasser gespeichert wird.","translation":"That leads to less groundwater being stored."},{"sentence":"Die Entwaldung führt dazu, dass mehr CO₂ in die Atmosphäre gelangt.","translation":"Deforestation leads to more CO₂ entering the atmosphere."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Dürre'' means?","options":["drought","dry period","arid spell","heat"],"correctAnswer":"drought"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Climate change is causing extreme weather events to occur more frequently.","options":["Der Klimawandel führt dazu, dass Extremwetterereignisse häufiger auftreten.","Extremwetter ist häufiger wegen Klimawandel.","Klimawandel verursacht Extremwetter.","Wetterereignisse werden häufiger."],"correctAnswer":"Der Klimawandel führt dazu, dass Extremwetterereignisse häufiger auftreten."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das führt dazu, dass weniger Grundwasser ___ wird.","options":["gespeichert","gespeichert worden","zu speichern","speichert"],"correctAnswer":"gespeichert"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Deforestation leads to more CO₂ entering the atmosphere","wordBankItems":["Die","Entwaldung","führt","dazu",",","dass","mehr","CO₂","in","die","Atmosphäre","gelangt","."],"correctAnswer":"Die Entwaldung führt dazu , dass mehr CO₂ in die Atmosphäre gelangt ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Auftreten'' in weather context means?","options":["to occur/appear","to step up","to arise","to emerge"],"correctAnswer":"to occur/appear"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000131',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss extreme weather events","Use Katastrophenschutz vocabulary","Talk about emergency response"],"explanation":{"intro":"Extreme weather vocabulary at B1 covers disasters, emergency response, and climate resilience.","culturalNote":"Germany has experienced major floods (Ahrtal 2021 — catastrophic), storms, and heatwaves. The BBK (Bundesamt für Bevölkerungsschutz und Katastrophenhilfe) coordinates disaster response. The concept of Resilienz (resilience) is now central to urban planning."},"examples":[{"german":"Nach der Flutkatastrophe 2021 wurden hunderte Ortschaften im Ahrtal zerstört.","english":"After the 2021 flood disaster, hundreds of places in the Ahr valley were destroyed."},{"german":"Katastrophenschutz erfordert die Zusammenarbeit von Bund, Ländern und Kommunen.","english":"Civil protection requires cooperation between federal, state, and local authorities."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss extreme weather, disaster response, and climate resilience in German."}}',
'{"items":[{"word":"die Flutkatastrophe","translation":"flood disaster","pronunciation":"dee FLOOT-kah-tah-stroh-feh","example":"Eine Flutkatastrophe."},{"word":"zerstören","translation":"to destroy","pronunciation":"tser-SHTÖ-ren","example":"Zerstört werden."},{"word":"der Katastrophenschutz","translation":"civil/disaster protection","pronunciation":"dayr kah-tah-STROH-fen-shoots","example":"Katastrophenschutz."},{"word":"die Zusammenarbeit","translation":"cooperation/collaboration","pronunciation":"dee tsoo-ZAM-en-ar-byt","example":"Enge Zusammenarbeit."},{"word":"die Resilienz","translation":"resilience","pronunciation":"dee reh-zee-lee-ENTS","example":"Resilienz aufbauen."},{"word":"evakuieren","translation":"to evacuate","pronunciation":"eh-vah-koo-EER-en","example":"Bewohner evakuieren."}]}',
'{"title":"Erfordern vs. benötigen vs. brauchen — require/need","pattern":"erfordern (formal requirement), benötigen (formal need), brauchen (everyday need)","explanation":"Three words for require/need with different register: 1) Erfordern (formal — something structurally requires): Das erfordert Zusammenarbeit = That requires cooperation. 2) Benötigen (formal-moderate need): Wir benötigen Ihr Einverständnis = We need your consent. 3) Brauchen (everyday): Ich brauche Hilfe = I need help. For formal texts: prefer erfordern (inherent requirement) or benötigen over brauchen.","examples":[{"sentence":"Diese Aufgabe erfordert besondere Fachkenntnisse.","translation":"This task requires special expertise."},{"sentence":"Wir benötigen zusätzliche Ressourcen.","translation":"We need additional resources."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Resilienz'' means?","options":["resilience","resistance","strength","stability"],"correctAnswer":"resilience"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Civil protection requires cooperation between federal, state, and local authorities.","options":["Katastrophenschutz erfordert die Zusammenarbeit von Bund, Ländern und Kommunen.","Bund, Länder und Kommunen arbeiten zusammen.","Katastrophenschutz ist wichtig.","Zusammenarbeit schützt vor Katastrophen."],"correctAnswer":"Katastrophenschutz erfordert die Zusammenarbeit von Bund, Ländern und Kommunen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Diese Aufgabe erfordert besondere ___.","options":["Fachkenntnisse","Fachkenntnis","Kenntnisse","Wissen"],"correctAnswer":"Fachkenntnisse"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: We need additional resources","wordBankItems":["Wir","benötigen","zusätzliche","Ressourcen","."],"correctAnswer":"Wir benötigen zusätzliche Ressourcen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Evakuieren'' means?","options":["to evacuate","to clear","to remove","to rescue"],"correctAnswer":"to evacuate"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000132',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss water supply and management","Use Wasserversorgung vocabulary","Talk about water scarcity issues"],"explanation":{"intro":"Water vocabulary at B1 covers water supply, quality, and scarcity — increasingly important global topics.","culturalNote":"Germany has generally high-quality tap water (Trinkwasser). Water is managed by municipal Wasserwerke (waterworks). Groundwater protection (Grundwasserschutz) is strictly regulated. Globally, Wasserknappheit (water scarcity) is a growing concern — an important topic for B1 discussions."},"examples":[{"german":"Trinkwasser in Deutschland unterliegt strengen Qualitätskontrollen.","english":"Drinking water in Germany is subject to strict quality controls."},{"german":"In vielen Teilen der Welt ist der Zugang zu sauberem Wasser nicht selbstverständlich.","english":"In many parts of the world access to clean water is not taken for granted."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss water supply, water quality, and water scarcity in German."}}',
'{"items":[{"word":"das Trinkwasser","translation":"drinking water","pronunciation":"dahs TRINK-vas-er","example":"Sauberes Trinkwasser."},{"word":"unterliegen","translation":"to be subject to/fall under","pronunciation":"OON-ter-lee-gen","example":"Kontrollen unterliegen."},{"word":"streng","translation":"strict/stringent","pronunciation":"shtreng","example":"Strenge Kontrollen."},{"word":"die Qualitätskontrolle","translation":"quality control","pronunciation":"dee kva-lee-TÄTS-kon-trol-eh","example":"Qualitätskontrolle."},{"word":"selbstverständlich","translation":"taken for granted/self-evident","pronunciation":"ZELPST-fer-shtent-likh","example":"Nicht selbstverständlich."},{"word":"die Wasserknappheit","translation":"water scarcity","pronunciation":"dee VAS-er-knap-hyt","example":"Wasserknappheit droht."}]}',
'{"title":"Unterliegen + dative — to be subject to/governed by","pattern":"etwas unterliegt + dative (something is subject to/falls under/governed by)","explanation":"Unterliegen + dative = to be subject to, fall under, be governed by. Das Trinkwasser unterliegt strengen Kontrollen = Drinking water is subject to strict controls. Das unterliegt dem Datenschutzgesetz = That falls under data protection law. Strong verb: unterliegt, unterlag, unterlegen. Also: jemandem unterliegen = to lose to someone (in competition). Context distinguishes the two meanings.","examples":[{"sentence":"Der Vertrag unterliegt deutschem Recht.","translation":"The contract is subject to German law."},{"sentence":"Dieser Bereich unterliegt strengen Sicherheitsvorschriften.","translation":"This area is subject to strict safety regulations."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Selbstverständlich'' means?","options":["taken for granted/self-evident","of course","naturally","obvious"],"correctAnswer":"taken for granted/self-evident"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Drinking water in Germany is subject to strict quality controls.","options":["Trinkwasser in Deutschland unterliegt strengen Qualitätskontrollen.","Deutsches Trinkwasser ist sauber.","Qualitätskontrollen gibt es für Trinkwasser.","Deutsches Wasser ist kontrolliert."],"correctAnswer":"Trinkwasser in Deutschland unterliegt strengen Qualitätskontrollen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Der Vertrag unterliegt deutschem ___.","options":["Recht","Rechts","Rechten","dem Recht"],"correctAnswer":"Recht"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: This area is subject to strict safety regulations","wordBankItems":["Dieser","Bereich","unterliegt","strengen","Sicherheitsvorschriften","."],"correctAnswer":"Dieser Bereich unterliegt strengen Sicherheitsvorschriften ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Unterliegen'' + dative means?","options":["to be subject to","to lie under","to be governed by","to fall under"],"correctAnswer":"to be subject to"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000133',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss forest dieback","Use Waldsterben vocabulary","Talk about Germany''s forest crisis"],"explanation":{"intro":"Forest dieback vocabulary covers the ongoing crisis of German forests under climate stress.","culturalNote":"Waldsterben (forest dieback) was a major environmental concern in the 1980s — originally from acid rain, now from drought and bark beetles (Borkenkäfer). About 30% of German forests are damaged. The Forst (managed forest) vs. Wald (natural forest) distinction is culturally important. Germans have a deep spiritual connection to their forests (''German forest'' as cultural symbol)."},"examples":[{"german":"Der Borkenkäfer hat in trockenen Sommern Millionen von Fichten befallen.","english":"The bark beetle has infested millions of spruce trees in dry summers."},{"german":"Das Waldsterben ist kein neues Phänomen — schon in den 80ern wurde Alarm geschlagen.","english":"Forest dieback is not a new phenomenon — alarm was raised as early as the 80s."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss forest dieback, tree diseases, and forest conservation in German."}}',
'{"items":[{"word":"der Borkenkäfer","translation":"bark beetle","pronunciation":"dayr BOR-ken-käy-fer","example":"Borkenkäferbefall."},{"word":"befallen","translation":"to infest/attack","pronunciation":"beh-FAL-en","example":"Bäume befallen."},{"word":"das Waldsterben","translation":"forest dieback","pronunciation":"dahs VALT-ster-ben","example":"Das Waldsterben."},{"word":"Alarm schlagen","translation":"to raise the alarm","pronunciation":"ah-LARM SHLAH-gen","example":"Alarm schlagen."},{"word":"das Phänomen","translation":"phenomenon","pronunciation":"dahs fäy-noh-MEN","example":"Ein Phänomen."},{"word":"abholzen","translation":"to deforest/fell","pronunciation":"AP-hol-tsen","example":"Wälder abholzen."}]}',
'{"title":"Kein neues Phänomen — negation with kein in predicate","pattern":"etwas ist kein + adjective + noun (to negate with kein — not a/no)","explanation":"Kein negates nouns (unlike nicht which negates verbs/adjectives). Das ist kein neues Phänomen = That is not a new phenomenon. Das ist kein Problem = That is not a problem. Kein + adjective + noun in predicate: kein uses adjective ending based on gender: kein neues Phänomen (neuter), keine neue Idee (feminine), kein neuer Versuch (masculine). Learning the kein declension parallels ein declension.","examples":[{"sentence":"Das ist kein einfaches Problem.","translation":"That is not a simple problem."},{"sentence":"Es ist keine neue Erkenntnis, dass Bewegung gesund ist.","translation":"It is not a new finding that exercise is healthy."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Abholzen'' means?","options":["to deforest/fell","to log","to clear-cut","to remove trees"],"correctAnswer":"to deforest/fell"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The bark beetle has infested millions of spruce trees in dry summers.","options":["Der Borkenkäfer hat in trockenen Sommern Millionen von Fichten befallen.","Borkenkäfer zerstören Fichten.","In trockenen Sommern leiden die Wälder.","Fichten werden vom Käfer befallen."],"correctAnswer":"Der Borkenkäfer hat in trockenen Sommern Millionen von Fichten befallen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das ist kein ___ Problem.","options":["einfaches","einfache","einfachem","einfachen"],"correctAnswer":"einfaches"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: It is not a new finding that exercise is healthy","wordBankItems":["Es","ist","keine","neue","Erkenntnis",",","dass","Bewegung","gesund","ist","."],"correctAnswer":"Es ist keine neue Erkenntnis , dass Bewegung gesund ist ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Alarm schlagen'' means?","options":["to raise the alarm","to sound the alarm","to warn","to alert"],"correctAnswer":"to raise the alarm"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000134',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss biodiversity","Use Artenvielfalt vocabulary","Talk about extinction and conservation"],"explanation":{"intro":"Biodiversity vocabulary at B1 covers the richness of species and the threats they face.","culturalNote":"Germany has lost significant biodiversity — insect populations have declined by up to 75% in some areas. Insektensterben (insect die-off) became a major political topic in the 2010s. The Volksbegehren Artenvielfalt (biodiversity referendum) in Bavaria gathered 1.75 million signatures in 2019."},"examples":[{"german":"Das Insektensterben bedroht nicht nur einzelne Arten, sondern das gesamte Ökosystem.","english":"Insect die-off threatens not only individual species but the entire ecosystem."},{"german":"Ohne Bestäuber wie Bienen könnten viele Nutzpflanzen nicht gedeihen.","english":"Without pollinators like bees, many crop plants could not thrive."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss biodiversity, species extinction, and conservation in German."}}',
'{"items":[{"word":"das Insektensterben","translation":"insect die-off","pronunciation":"dahs in-ZEK-ten-ster-ben","example":"Das Insektensterben."},{"word":"der Bestäuber","translation":"pollinator","pronunciation":"dayr beh-SHTOY-ber","example":"Bestäuber schützen."},{"word":"gedeihen","translation":"to thrive/flourish","pronunciation":"geh-DY-en","example":"Gut gedeihen."},{"word":"die Nutzpflanze","translation":"crop plant/useful plant","pronunciation":"dee NOOTS-pflan-tseh","example":"Nutzpflanzen."},{"word":"nicht nur...sondern","translation":"not only...but also","pronunciation":"nikht noor...zon-dern","example":"Nicht nur...sondern auch."},{"word":"der Bestand","translation":"stock/population (biological)","pronunciation":"dayr beh-SHTANT","example":"Der Tierbestand."}]}',
'{"title":"Nicht nur ... sondern (auch) — not only ... but (also)","pattern":"nicht nur + noun/clause, sondern (auch) + noun/clause — not only X but (also) Y","explanation":"Nicht nur...sondern (auch) = not only X but (also) Y. Das bedroht nicht nur Bienen, sondern auch Schmetterlinge = That threatens not only bees but also butterflies. Grammatically: nach sondern, verb-second in main clause position; nach nicht nur, normal main clause. Sondern (not aber) = but when negating and substituting. Nicht nur A, sondern auch B — both receive emphasis.","examples":[{"sentence":"Das betrifft nicht nur Deutschland, sondern ganz Europa.","translation":"That affects not only Germany but the whole of Europe."},{"sentence":"Das Projekt ist nicht nur teuer, sondern auch zeitaufwendig.","translation":"The project is not only expensive but also time-consuming."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Gedeihen'' means?","options":["to thrive/flourish","to grow","to develop","to prosper"],"correctAnswer":"to thrive/flourish"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Without pollinators like bees, many crop plants could not thrive.","options":["Ohne Bestäuber wie Bienen könnten viele Nutzpflanzen nicht gedeihen.","Bienen sind wichtig für Pflanzen.","Ohne Bienen wachsen Pflanzen nicht.","Bestäuber brauchen Pflanzen."],"correctAnswer":"Ohne Bestäuber wie Bienen könnten viele Nutzpflanzen nicht gedeihen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das betrifft nicht nur Deutschland, sondern ganz ___.","options":["Europa","Europas","Europäisch","Europäern"],"correctAnswer":"Europa"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The project is not only expensive but also time-consuming","wordBankItems":["Das","Projekt","ist","nicht","nur","teuer",",","sondern","auch","zeitaufwendig","."],"correctAnswer":"Das Projekt ist nicht nur teuer , sondern auch zeitaufwendig ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Nicht nur...sondern'' uses which conjunction for the second part?","options":["sondern","aber","doch","jedoch"],"correctAnswer":"sondern"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000135',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss sustainable tourism","Use Ökotourismus vocabulary","Talk about responsible travel"],"explanation":{"intro":"Sustainable tourism vocabulary covers eco-tourism, responsible travel, and the balance between tourism and conservation.","culturalNote":"Germany is a major tourism destination (Schwarzwald, Bayern, Nordseeküste, Berlin). Overtourism (Massentourismus) is a growing concern. Sanfter Tourismus (gentle tourism) and Ökotourismus (eco-tourism) are promoted. The Deutschen Wanderverband (German Hiking Association) promotes sustainable hiking."},"examples":[{"german":"Nachhaltiger Tourismus zielt darauf ab, Natur und Kultur zu schützen.","english":"Sustainable tourism aims to protect nature and culture."},{"german":"Massentourismus kann die Umwelt belasten und lokale Gemeinschaften überfordern.","english":"Mass tourism can strain the environment and overwhelm local communities."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss sustainable tourism and responsible travel in German."}}',
'{"items":[{"word":"darauf abzielen","translation":"to aim to/at","pronunciation":"dah-ROWF AP-tsee-len","example":"Darauf abzielen, zu schützen."},{"word":"der Massentourismus","translation":"mass tourism","pronunciation":"dayr MAS-en-too-ris-moos","example":"Massentourismus."},{"word":"belasten","translation":"to strain/burden","pronunciation":"beh-LAS-ten","example":"Die Umwelt belasten."},{"word":"überfordern","translation":"to overwhelm","pronunciation":"ü-ber-FOR-dern","example":"Überfordert sein."},{"word":"die Gemeinschaft","translation":"community","pronunciation":"dee geh-MYN-shaft","example":"Lokale Gemeinschaft."},{"word":"schonend","translation":"gentle/careful","pronunciation":"SHOH-nend","example":"Schonend umgehen."}]}',
'{"title":"Darauf abzielen, zu — to aim to","pattern":"etwas zielt darauf ab, zu + Infinitiv (something aims to, targets)","explanation":"Abzielen auf + accusative = to aim at/for. With zu-infinitive: auf etw abzielen, etwas zu tun = to aim to do something. Das Projekt zielt darauf ab, Emissionen zu reduzieren = The project aims to reduce emissions. Darauf is an anticipatory da-compound for the zu-infinitive clause. Separable: zielt...ab. Perfect: hat darauf abgezielt. Compare: anstreben (to strive for), versuchen (to try).","examples":[{"sentence":"Das Programm zielt darauf ab, benachteiligte Gruppen zu unterstützen.","translation":"The programme aims to support disadvantaged groups."},{"sentence":"Die Maßnahme zielt darauf ab, Energie zu sparen.","translation":"The measure aims to save energy."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Überfordern'' means?","options":["to overwhelm","to over-demand","to tax too heavily","to over-challenge"],"correctAnswer":"to overwhelm"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Sustainable tourism aims to protect nature and culture.","options":["Nachhaltiger Tourismus zielt darauf ab, Natur und Kultur zu schützen.","Nachhaltiger Tourismus ist gut.","Tourismus schützt die Natur.","Natur und Kultur werden geschützt."],"correctAnswer":"Nachhaltiger Tourismus zielt darauf ab, Natur und Kultur zu schützen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Maßnahme zielt darauf ab, Energie zu ___.","options":["sparen","gespart","sparen werden","zu sparen"],"correctAnswer":"sparen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The programme aims to support disadvantaged groups","wordBankItems":["Das","Programm","zielt","darauf","ab",",","benachteiligte","Gruppen","zu","unterstützen","."],"correctAnswer":"Das Programm zielt darauf ab , benachteiligte Gruppen zu unterstützen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Belasten'' means?","options":["to strain/burden","to load","to tax","to stress"],"correctAnswer":"to strain/burden"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000136',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss urban green spaces","Use Stadtgrün vocabulary","Talk about urban ecology"],"explanation":{"intro":"Urban green spaces vocabulary covers parks, urban ecology, and the role of nature in cities.","culturalNote":"German cities invest heavily in Stadtgrün (urban greenery): parks, street trees, green roofs, community gardens. The Berliner Tempelhof field is a famous example of urban open space preserved as public park. Urban heat islands (städtische Wärmeinseln) are addressed through greening strategies."},"examples":[{"german":"Grünflächen in der Stadt verbessern die Luftqualität und kühlen die Umgebung.","english":"Green spaces in the city improve air quality and cool the surroundings."},{"german":"Städtische Wärmeinseln entstehen durch Beton und Asphalt ohne Vegetation.","english":"Urban heat islands form due to concrete and asphalt without vegetation."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss urban green spaces, urban ecology, and sustainable urban planning."}}',
'{"items":[{"word":"die Grünfläche","translation":"green space","pronunciation":"dee GRÜN-fläkh-eh","example":"Städtische Grünflächen."},{"word":"die Luftqualität","translation":"air quality","pronunciation":"dee LOOFT-kvah-lee-TÄT","example":"Luftqualität verbessern."},{"word":"die Wärmeinsel","translation":"heat island","pronunciation":"dee VÄR-meh-in-zel","example":"Städtische Wärmeinsel."},{"word":"entstehen","translation":"to form/arise/develop","pronunciation":"ent-SHTAY-en","example":"Wärmeinseln entstehen."},{"word":"die Begrünung","translation":"greening/planting","pronunciation":"dee beh-GRÜN-oong","example":"Fassadenbegrünung."},{"word":"kühlen","translation":"to cool","pronunciation":"KÜ-len","example":"Die Umgebung kühlen."}]}',
'{"title":"Entstehen durch — to arise/form due to","pattern":"etwas entsteht durch + accusative (to arise, form, develop as a result of)","explanation":"Entstehen (strong, intransitive, sein) = to arise, come into being, develop. Entstehen durch + accusative = to arise due to/as a result of. Die Probleme entstanden durch den Klimawandel = The problems arose due to climate change. Past: entstand. Participle: entstanden. Note: entstehen is spontaneous development — contrast: erzeugen (to produce — deliberate), schaffen (to create — deliberate), verursachen (to cause — deliberate).","examples":[{"sentence":"Das Feuer entstand durch Fahrlässigkeit.","translation":"The fire arose due to negligence."},{"sentence":"Neue Möglichkeiten entstehen oft aus Krisen.","translation":"New possibilities often arise from crises."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Begrünung'' means?","options":["greening/planting","vegetation","green cover","landscaping"],"correctAnswer":"greening/planting"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Urban heat islands form due to concrete and asphalt without vegetation.","options":["Städtische Wärmeinseln entstehen durch Beton und Asphalt ohne Vegetation.","Beton macht Städte wärmer.","Ohne Pflanzen ist die Stadt heiß.","Städte werden durch Beton wärmer."],"correctAnswer":"Städtische Wärmeinseln entstehen durch Beton und Asphalt ohne Vegetation."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Neue Möglichkeiten entstehen oft aus ___.","options":["Krisen","Krise","Krisenzeit","der Krise"],"correctAnswer":"Krisen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The fire arose due to negligence","wordBankItems":["Das","Feuer","entstand","durch","Fahrlässigkeit","."],"correctAnswer":"Das Feuer entstand durch Fahrlässigkeit ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Kühlen'' means?","options":["to cool","to refrigerate","to chill","to lower temperature"],"correctAnswer":"to cool"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000137',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss transport and mobility","Use Verkehr vocabulary","Talk about sustainable transport"],"explanation":{"intro":"Transport vocabulary at B1 covers traffic, mobility solutions, and sustainable transport policy.","culturalNote":"Germany has excellent infrastructure but also severe Stau (traffic jams) — especially on the A autobahn network. The Dieselskandal (VW emissions scandal, 2015) shook trust in the car industry. Fahrverbote (driving bans) for diesel cars were implemented in some cities. The 49-Euro-Ticket democratised public transport in 2023."},"examples":[{"german":"Der Stau auf der Autobahn kostete mich zwei Stunden — ich hätte den Zug nehmen sollen.","english":"The traffic jam on the motorway cost me two hours — I should have taken the train."},{"german":"Das 49-Euro-Ticket hat den öffentlichen Nahverkehr für viele erschwinglich gemacht.","english":"The 49-euro ticket made public transport affordable for many."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss transport, traffic, and sustainable mobility in German."}}',
'{"items":[{"word":"der Stau","translation":"traffic jam/congestion","pronunciation":"dayr shtow","example":"Im Stau stehen."},{"word":"kosten","translation":"to cost (also: to take — time)","pronunciation":"KOS-ten","example":"Zwei Stunden kosten."},{"word":"das Fahrverbot","translation":"driving ban","pronunciation":"dahs FAR-fer-boht","example":"Fahrverbot für Diesel."},{"word":"erschwinglich machen","translation":"to make affordable","pronunciation":"er-SHVING-likh MAKH-en","example":"Erschwinglich machen."},{"word":"das Pendeln","translation":"commuting","pronunciation":"dahs PEN-deln","example":"Das tägliche Pendeln."},{"word":"die Infrastruktur","translation":"infrastructure","pronunciation":"dee in-frah-shtrook-TOOR","example":"Die Infrastruktur."}]}',
'{"title":"Hätte ... sollen — should have (modal in past/Konjunktiv II)","pattern":"hätte + Infinitiv + sollen (should have done — past regret/missed obligation)","explanation":"Should have = hätte + infinitive + sollen. Ich hätte den Zug nehmen sollen = I should have taken the train. The structure: auxiliary hätte + two infinitives (Ersatzinfinitiv). Compare: hätte ... müssen (would have had to), hätte ... können (could have). These express regret or missed opportunity. Very common in everyday speech for past regret.","examples":[{"sentence":"Du hättest früher kommen sollen.","translation":"You should have come earlier."},{"sentence":"Er hätte das besser erklären können.","translation":"He could have explained that better."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Stau'' means?","options":["traffic jam","congestion","standstill","blockage"],"correctAnswer":"traffic jam"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The traffic jam on the motorway cost me two hours — I should have taken the train.","options":["Der Stau auf der Autobahn kostete mich zwei Stunden — ich hätte den Zug nehmen sollen.","Im Stau stand ich zwei Stunden.","Der Zug wäre besser gewesen.","Ich bin im Stau gestanden."],"correctAnswer":"Der Stau auf der Autobahn kostete mich zwei Stunden — ich hätte den Zug nehmen sollen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Du ___ früher kommen sollen.","options":["hättest","hätte","solltest","sollst"],"correctAnswer":"hättest"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: He could have explained that better","wordBankItems":["Er","hätte","das","besser","erklären","können","."],"correctAnswer":"Er hätte das besser erklären können ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Das Pendeln'' means?","options":["commuting","commute","travelling","daily travel"],"correctAnswer":"commuting"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000138',1,'APPROVED','PUBLISHED',
'{"objectives":["Use public transport in Germany","Use ÖPNV vocabulary","Navigate German transit systems"],"explanation":{"intro":"Public transport vocabulary at B1 covers navigating German transit systems — practical and essential.","culturalNote":"Germany''s ÖPNV (Öffentlicher Personennahverkehr) includes S-Bahn, U-Bahn, Tram, and Bus. The Deutsche Bahn (DB) operates long-distance trains. Pünktlichkeit (punctuality) is valued but delays are common. The Schwarzfahren (fare dodging) is prosecuted. Tickets must be validated (entwerten)."},"examples":[{"german":"Der Zug hat zehn Minuten Verspätung — ich muss meinen Anschluss ändern.","english":"The train has ten minutes delay — I need to change my connection."},{"german":"Bitte lösen Sie Ihr Ticket vor der Abfahrt am Automaten.","english":"Please buy your ticket at the machine before departure."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can navigate German public transport systems and handle common situations."}}',
'{"items":[{"word":"die Verspätung","translation":"delay","pronunciation":"dee fer-SHPÄY-toong","example":"Zehn Minuten Verspätung."},{"word":"der Anschluss","translation":"connection (transport)","pronunciation":"dayr AN-shloos","example":"Den Anschluss verpassen."},{"word":"lösen","translation":"to buy/purchase (ticket)","pronunciation":"LÖ-zen","example":"Ein Ticket lösen."},{"word":"der Automat","translation":"machine/vending machine","pronunciation":"dayr ow-toh-MAHT","example":"Am Automat kaufen."},{"word":"entwerten","translation":"to validate (ticket)","pronunciation":"ent-VER-ten","example":"Das Ticket entwerten."},{"word":"das Schwarzfahren","translation":"fare dodging","pronunciation":"dahs SHVARTS-fah-ren","example":"Schwarzfahren ist verboten."}]}',
'{"title":"Verspätung haben — to be delayed","pattern":"der Zug/das Flugzeug hat X Minuten Verspätung (the train/flight is X minutes delayed)","explanation":"Verspätung haben = to be delayed (transport). Der Zug hat 20 Minuten Verspätung = The train is 20 minutes delayed. Sich verspäten = to be late (person): Ich habe mich verspätet = I was late. Die Verspätung (noun) = the delay. Pünktlich ankommen = to arrive on time. Mit Verspätung ankommen = to arrive with a delay. Fahrplanmäßig = according to schedule.","examples":[{"sentence":"Der ICE hat aufgrund von Bauarbeiten eine halbe Stunde Verspätung.","translation":"The ICE has half an hour''s delay due to construction work."},{"sentence":"Ich habe mich entschuldigt, weil ich mich verspätet hatte.","translation":"I apologised because I had been late."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Entwerten'' in public transport means?","options":["to validate","to buy","to stamp","to cancel"],"correctAnswer":"to validate"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The train has ten minutes delay — I need to change my connection.","options":["Der Zug hat zehn Minuten Verspätung — ich muss meinen Anschluss ändern.","Der Zug ist spät.","Ich verpasse meinen Anschluss.","Zehn Minuten sind lang."],"correctAnswer":"Der Zug hat zehn Minuten Verspätung — ich muss meinen Anschluss ändern."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Der ICE hat aufgrund von Bauarbeiten eine halbe Stunde ___.","options":["Verspätung","Verzögerung","Wartezeit","Zeitverlust"],"correctAnswer":"Verspätung"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I apologised because I had been late","wordBankItems":["Ich","habe","mich","entschuldigt",",","weil","ich","mich","verspätet","hatte","."],"correctAnswer":"Ich habe mich entschuldigt , weil ich mich verspätet hatte ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Lösen'' in ticket context means?","options":["to buy/purchase","to solve","to release","to get"],"correctAnswer":"to buy/purchase"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000139',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss cycling and walking","Use Fahrrad vocabulary","Talk about active mobility"],"explanation":{"intro":"Cycling and walking vocabulary covers active transport options — increasingly important in German cities.","culturalNote":"Germany has excellent cycling infrastructure, especially in cities like Münster (most cycle-friendly), Freiburg, and Karlsruhe. The ADFC (German Cycling Association) advocates for cyclists. Fahrradwege (cycle paths) are part of standard urban design. E-Bikes are increasingly popular — especially for commuting."},"examples":[{"german":"In Münster ist das Fahrrad das häufigste Verkehrsmittel.","english":"In Münster the bicycle is the most common means of transport."},{"german":"Das Radwegenetz in deutschen Städten wird kontinuierlich ausgebaut.","english":"The cycle path network in German cities is being continuously expanded."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss cycling, walking, and active mobility in German."}}',
'{"items":[{"word":"das Verkehrsmittel","translation":"means of transport","pronunciation":"dahs fer-KAYRS-mit-el","example":"Das häufigste Verkehrsmittel."},{"word":"das Radwegenetz","translation":"cycle path network","pronunciation":"dahs RAHD-vay-geh-nets","example":"Das Radwegenetz."},{"word":"kontinuierlich","translation":"continuously/steadily","pronunciation":"kon-tee-noo-EER-likh","example":"Kontinuierlich ausbauen."},{"word":"ausbauen","translation":"to expand/develop","pronunciation":"OWS-bow-en","example":"Das Netz ausbauen."},{"word":"der Fußgänger","translation":"pedestrian","pronunciation":"dayr FOOS-geng-er","example":"Fußgänger schützen."},{"word":"die Radfahrerin","translation":"cyclist (f)","pronunciation":"dee RAHD-fah-reh-rin","example":"Eine Radfahrerin."}]}',
'{"title":"Kontinuierlich — continuously (adverb)","pattern":"kontinuierlich + verb (to continuously, steadily, on an ongoing basis)","explanation":"Kontinuierlich = continuously, on an ongoing basis (without interruption). Das Netz wird kontinuierlich ausgebaut = The network is being continuously expanded. Compare: stetig (steadily — gradual increase), laufend (ongoing — administrative), ständig (constantly — often implies too much). Kontinuierlich is formal and neutral — preferred in official/journalistic German for ongoing processes.","examples":[{"sentence":"Die Qualität verbessert sich kontinuierlich.","translation":"Quality is continuously improving."},{"sentence":"Wir arbeiten kontinuierlich an der Optimierung.","translation":"We are continuously working on optimisation."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Verkehrsmittel'' means?","options":["means of transport","vehicle","transportation","mode of travel"],"correctAnswer":"means of transport"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"In Münster the bicycle is the most common means of transport.","options":["In Münster ist das Fahrrad das häufigste Verkehrsmittel.","Münster hat viele Fahrräder.","In Münster fahren viele Rad.","Fahrräder sind in Münster beliebt."],"correctAnswer":"In Münster ist das Fahrrad das häufigste Verkehrsmittel."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Qualität verbessert sich ___.","options":["kontinuierlich","kontinuiert","kontinuierend","stetigem"],"correctAnswer":"kontinuierlich"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: We are continuously working on optimisation","wordBankItems":["Wir","arbeiten","kontinuierlich","an","der","Optimierung","."],"correctAnswer":"Wir arbeiten kontinuierlich an der Optimierung ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Ausbauen'' means?","options":["to expand/develop","to build out","to extend","to improve"],"correctAnswer":"to expand/develop"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000013a',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss electric mobility","Use Elektroauto vocabulary","Talk about the EV transition"],"explanation":{"intro":"Electric mobility vocabulary covers the shift to electric vehicles and associated infrastructure.","culturalNote":"Germany''s auto industry (BMW, Mercedes, VW, Audi, Porsche) is transitioning to electric. E-Auto sales are growing but still low compared to targets. Ladeinfrastruktur (charging infrastructure) is being expanded. From 2035, new combustion engines will be banned in the EU. Tesla disrupted German carmakers."},"examples":[{"german":"Die Reichweite von Elektroautos hat sich in den letzten Jahren deutlich verbessert.","english":"The range of electric cars has improved significantly in recent years."},{"german":"Das flächendeckende Netz von Ladestationen ist eine Voraussetzung für die Elektromobilität.","english":"A comprehensive network of charging stations is a precondition for electric mobility."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss electric vehicles, charging infrastructure, and the EV transition in German."}}',
'{"items":[{"word":"die Reichweite","translation":"range","pronunciation":"dee RYKH-vy-teh","example":"Die Reichweite des Autos."},{"word":"die Ladestation","translation":"charging station","pronunciation":"dee LAH-deh-shta-tsyohn","example":"Eine Ladestation."},{"word":"flächendeckend","translation":"comprehensive/nationwide","pronunciation":"FLÄY-khen-dek-end","example":"Flächendeckend verfügbar."},{"word":"die Voraussetzung","translation":"precondition/requirement","pronunciation":"dee for-OWS-zet-soong","example":"Eine Voraussetzung."},{"word":"tanken","translation":"to fill up/charge","pronunciation":"TANK-en","example":"Das E-Auto tanken."},{"word":"die Antriebsart","translation":"drive type/powertrain","pronunciation":"dee AN-treeps-art","example":"Verschiedene Antriebsarten."}]}',
'{"title":"Flächendeckend — comprehensive/nationwide","pattern":"flächendeckend + adjective/adverb (covering the whole area — nationwide, comprehensive)","explanation":"Flächendeckend = covering the whole area, nationwide, comprehensive (from Fläche = area + deckend = covering). Das Netz ist flächendeckend = The network is nationwide. Ein flächendeckendes Angebot = a nationwide/comprehensive offer. Very common for infrastructure, services, and policies. Not to be confused with flächengreifend (not standard German).","examples":[{"sentence":"Schnelles Internet ist in Deutschland noch nicht flächendeckend verfügbar.","translation":"Fast internet is not yet available nationwide in Germany."},{"sentence":"Der Service wird bald flächendeckend angeboten.","translation":"The service will soon be offered nationwide."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Reichweite'' means?","options":["range","reach","coverage","capacity"],"correctAnswer":"range"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"A comprehensive network of charging stations is a precondition for electric mobility.","options":["Das flächendeckende Netz von Ladestationen ist eine Voraussetzung für die Elektromobilität.","Wir brauchen Ladestationen.","Elektroautos brauchen Infrastruktur.","Ladestationen sind wichtig für E-Autos."],"correctAnswer":"Das flächendeckende Netz von Ladestationen ist eine Voraussetzung für die Elektromobilität."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Schnelles Internet ist in Deutschland noch nicht ___ verfügbar.","options":["flächendeckend","landesweit","allgemein","überall"],"correctAnswer":"flächendeckend"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The service will soon be offered nationwide","wordBankItems":["Der","Service","wird","bald","flächendeckend","angeboten","."],"correctAnswer":"Der Service wird bald flächendeckend angeboten ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Voraussetzung'' means?","options":["precondition/requirement","assumption","condition","prerequisite"],"correctAnswer":"precondition/requirement"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000013b',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss the circular economy","Use Kreislaufwirtschaft vocabulary","Talk about recycling and waste reduction"],"explanation":{"intro":"Circular economy vocabulary covers recycling, waste reduction, and closed-loop production systems.","culturalNote":"Germany has one of the world''s best recycling systems. The Duales System (Grüner Punkt) collects packaging. Pfand (deposit) on bottles is high — 25 cents on single-use plastic. Mülltrennung (waste separation) into Gelber Sack, Papiertonne, Biotonne, Restmüll is mandatory and culturally ingrained."},"examples":[{"german":"Deutschland hat eine der höchsten Recyclingquoten der Welt.","english":"Germany has one of the highest recycling rates in the world."},{"german":"Das Pfandsystem reduziert den Einwegplastikmüll erheblich.","english":"The deposit system significantly reduces single-use plastic waste."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss recycling, circular economy, and waste management in German."}}',
'{"items":[{"word":"die Recyclingquote","translation":"recycling rate","pronunciation":"dee reh-SY-kling-kvoh-teh","example":"Hohe Recyclingquote."},{"word":"das Pfandsystem","translation":"deposit system","pronunciation":"dahs PFANT-züs-tem","example":"Das Pfandsystem."},{"word":"der Einwegplastik","translation":"single-use plastic","pronunciation":"dayr YN-vayg-plas-tik","example":"Einwegplastik reduzieren."},{"word":"erheblich","translation":"significantly/considerably","pronunciation":"er-HAYP-likh","example":"Erheblich reduzieren."},{"word":"die Mülltrennung","translation":"waste separation","pronunciation":"dee MÜL-tren-oong","example":"Mülltrennung betreiben."},{"word":"der Wertstoff","translation":"recyclable material","pronunciation":"dayr VERT-shtof","example":"Wertstoffe sammeln."}]}',
'{"title":"Erheblich — significantly/considerably (formal adverb)","pattern":"erheblich + verb or comparative adjective (considerably — formal register)","explanation":"Erheblich = significantly, considerably, substantially (formal register — business, academic, legal). Erheblich gesunken/gestiegen = fallen/risen significantly. Ein erheblicher Unterschied = a considerable difference. Compare synonyms by register: erheblich (formal), wesentlich (formal — essential difference), beträchtlich (formal — notable), deutlich (moderate — clear, visible), stark (everyday — strongly), sehr (everyday — very).","examples":[{"sentence":"Die Kosten sind erheblich gestiegen.","translation":"The costs have risen considerably."},{"sentence":"Das hat die Situation erheblich verbessert.","translation":"That has considerably improved the situation."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Wertstoff'' means?","options":["recyclable material","valuable material","resource","raw material"],"correctAnswer":"recyclable material"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Germany has one of the highest recycling rates in the world.","options":["Deutschland hat eine der höchsten Recyclingquoten der Welt.","Deutschland recycelt viel.","Das Recycling in Deutschland ist gut.","Die Recyclingquote ist hoch."],"correctAnswer":"Deutschland hat eine der höchsten Recyclingquoten der Welt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Kosten sind ___ gestiegen.","options":["erheblich","erheblicher","erheblichst","erheblichem"],"correctAnswer":"erheblich"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: That has considerably improved the situation","wordBankItems":["Das","hat","die","Situation","erheblich","verbessert","."],"correctAnswer":"Das hat die Situation erheblich verbessert ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Erheblich'' is most similar to which register?","options":["formal/written","everyday/spoken","technical","bureaucratic"],"correctAnswer":"formal/written"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000013c',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss zero waste lifestyle","Use Minimalismus vocabulary","Talk about reducing consumption"],"explanation":{"intro":"Zero waste vocabulary covers minimalism, reducing consumption, and sustainable lifestyle choices.","culturalNote":"The Zero-Waste-Bewegung (zero waste movement) has a strong following in German-speaking countries. Unverpackt-Läden (unpackaged shops) are growing. Repair-Cafés allow people to repair items instead of throwing them away. The KonMari method (though Japanese) is popular in Germany."},"examples":[{"german":"Im Unverpackt-Laden kauft man Lebensmittel ohne Plastikverpackung.","english":"At the zero-packaging shop one buys food without plastic packaging."},{"german":"Weniger kaufen und Dinge reparieren statt wegwerfen — das ist das Zero-Waste-Prinzip.","english":"Buy less and repair things instead of throwing them away — that is the zero waste principle."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss zero waste lifestyle, minimalism, and sustainable consumption in German."}}',
'{"items":[{"word":"unverpackt","translation":"unpackaged/without packaging","pronunciation":"OON-fer-pakt","example":"Unverpackt kaufen."},{"word":"wegwerfen","translation":"to throw away","pronunciation":"VEK-ver-fen","example":"Etwas wegwerfen."},{"word":"reparieren","translation":"to repair","pronunciation":"reh-pah-REER-en","example":"Etwas reparieren."},{"word":"der Minimalismus","translation":"minimalism","pronunciation":"dayr mee-nee-mah-LIS-moos","example":"Minimalismus als Lebensstil."},{"word":"statt","translation":"instead of (preposition)","pronunciation":"shtat","example":"Statt kaufen, reparieren."},{"word":"die Verpackung","translation":"packaging","pronunciation":"dee fer-PAK-oong","example":"Verpackung vermeiden."}]}',
'{"title":"Statt + genitive/infinitive — instead of","pattern":"statt + genitive (noun) OR statt + zu + infinitive (instead of doing)","explanation":"Statt = instead of. + Genitive noun: statt eines neuen Geräts (instead of a new device). + Zu-infinitive (with same subject): statt es wegzuwerfen (instead of throwing it away). In everyday speech: statt des/einem → statt dem (dative increasingly accepted). Compare anstatt (formal variant — same grammar). Also anstatt...zu: anstatt zu schlafen = instead of sleeping.","examples":[{"sentence":"Er kaufte ein gebrauchtes Auto statt eines neuen.","translation":"He bought a used car instead of a new one."},{"sentence":"Statt es wegzuwerfen, spendete sie das Buch.","translation":"Instead of throwing it away, she donated the book."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Unverpackt'' means?","options":["unpackaged/without packaging","not packed","loose","bulk"],"correctAnswer":"unpackaged/without packaging"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Buy less and repair things instead of throwing them away — that is the zero waste principle.","options":["Weniger kaufen und Dinge reparieren statt wegwerfen — das ist das Zero-Waste-Prinzip.","Zero Waste bedeutet nicht kaufen.","Man soll Dinge behalten.","Reparieren ist besser als kaufen."],"correctAnswer":"Weniger kaufen und Dinge reparieren statt wegwerfen — das ist das Zero-Waste-Prinzip."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Er kaufte ein gebrauchtes Auto statt ___ neuen.","options":["eines","einem","ein","des"],"correctAnswer":"eines"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Instead of throwing it away, she donated the book","wordBankItems":["Statt","es","wegzuwerfen",",","spendete","sie","das","Buch","."],"correctAnswer":"Statt es wegzuwerfen , spendete sie das Buch ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Verpackung'' means?","options":["packaging","wrapping","container","cover"],"correctAnswer":"packaging"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000013d',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss food rescue","Use Lebensmittelrettung vocabulary","Talk about food waste reduction"],"explanation":{"intro":"Food rescue vocabulary covers initiatives to reduce food waste and redistribute surplus food.","culturalNote":"Germany wastes about 12 million tons of food annually. Foodsharing.de and Too Good To Go are popular apps for food rescue. Tafeln (food banks) redistribute surplus food to those in need. In Germany, supermarkets increasingly donate instead of destroy — though Containern (dumpster diving) is legally grey."},"examples":[{"german":"Die Tafel verteilt überschüssige Lebensmittel an Bedürftige.","english":"The food bank distributes surplus food to those in need."},{"german":"Zu Good To Go ermöglicht es, Essen zu retten, das sonst weggeworfen würde.","english":"Too Good To Go makes it possible to rescue food that would otherwise be thrown away."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss food rescue, food waste, and redistribution initiatives in German."}}',
'{"items":[{"word":"überschüssig","translation":"surplus/excess","pronunciation":"ü-ber-SHÜS-ikh","example":"Überschüssige Ware."},{"word":"der Bedürftige","translation":"person in need","pronunciation":"dayr beh-DÜRF-tee-geh","example":"Bedürftige unterstützen."},{"word":"verteilen","translation":"to distribute","pronunciation":"fer-TY-len","example":"Essen verteilen."},{"word":"ermöglichen","translation":"to make possible/enable","pronunciation":"er-MÖG-likh-en","example":"Etwas ermöglichen."},{"word":"die Lebensmittelverschwendung","translation":"food waste","pronunciation":"dee LAY-bens-mit-el-fer-shven-doong","example":"Lebensmittelverschwendung."},{"word":"retten","translation":"to rescue/save","pronunciation":"RET-en","example":"Essen retten."}]}',
'{"title":"Ermöglichen — to make possible/enable","pattern":"etwas ermöglicht (jemandem) etwas / etwas zu tun (something makes something possible/enables)","explanation":"Ermöglichen = to make possible, enable. Etwas ermöglicht etwas = something makes something possible: Die App ermöglicht die Bestellung = The app enables ordering. Ermöglichen + dative + accusative: Das ermöglicht ihm den Zugang = That enables him access. Or + dative + zu-infinitive: Das ermöglicht uns, pünktlich zu sein = That enables us to be on time. Die Ermöglichung (noun) = the enabling. Contrast: verhindern (to prevent).","examples":[{"sentence":"Das Stipendium ermöglichte ihr ein Studium im Ausland.","translation":"The scholarship made it possible for her to study abroad."},{"sentence":"Die Technik ermöglicht es, von überall zu arbeiten.","translation":"The technology makes it possible to work from anywhere."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Überschüssig'' means?","options":["surplus/excess","extra","additional","leftover"],"correctAnswer":"surplus/excess"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The food bank distributes surplus food to those in need.","options":["Die Tafel verteilt überschüssige Lebensmittel an Bedürftige.","Die Tafel hilft armen Menschen.","Überschüssiges Essen geht an die Tafel.","Bedürftige bekommen Essen."],"correctAnswer":"Die Tafel verteilt überschüssige Lebensmittel an Bedürftige."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Stipendium ermöglichte ihr ein Studium im ___.","options":["Ausland","Ausländern","Ausländisch","Auslandstudium"],"correctAnswer":"Ausland"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The technology makes it possible to work from anywhere","wordBankItems":["Die","Technik","ermöglicht","es",",","von","überall","zu","arbeiten","."],"correctAnswer":"Die Technik ermöglicht es , von überall zu arbeiten ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Retten'' means?","options":["to rescue/save","to recover","to preserve","to protect"],"correctAnswer":"to rescue/save"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000013e',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss veganism in Germany","Use Veganismus vocabulary","Talk about plant-based diets"],"explanation":{"intro":"Veganism vocabulary covers plant-based diets, ethical motivations, and Germany''s growing vegan scene.","culturalNote":"Germany is Europe''s top vegan market. Berlin has more vegan restaurants per capita than almost anywhere. The word Veganer is now standard. Oatly''s oat milk (Hafermilch), plant-based sausages (Bratwurst), and vegan cheese (veganer Käse) have mainstream presence. Veganismus often intersects with Klimabewusstsein."},"examples":[{"german":"Immer mehr Menschen entscheiden sich bewusst für eine vegane Ernährung.","english":"More and more people consciously decide in favour of a vegan diet."},{"german":"Vegane Produkte sind nicht mehr nur in Bioläden erhältlich, sondern auch im Supermarkt.","english":"Vegan products are no longer available only in organic shops but also in supermarkets."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss veganism, plant-based diets, and food ethics in German."}}',
'{"items":[{"word":"bewusst","translation":"consciously/deliberately","pronunciation":"beh-VOOST","example":"Bewusst entscheiden."},{"word":"sich entscheiden für","translation":"to decide in favour of","pronunciation":"zikh ent-SHY-den für","example":"Sich für etwas entscheiden."},{"word":"die Ernährung","translation":"diet/nutrition","pronunciation":"dee er-NÄY-roong","example":"Vegane Ernährung."},{"word":"erhältlich","translation":"available","pronunciation":"er-HÄLT-likh","example":"Erhältlich sein."},{"word":"der Verzicht auf","translation":"renunciation of/giving up","pronunciation":"dayr fer-TSIKHT owf","example":"Verzicht auf Fleisch."},{"word":"tierleidfrei","translation":"free from animal suffering","pronunciation":"TEER-lyt-fry","example":"Tierleidfrei leben."}]}',
'{"title":"Sich entscheiden für/gegen — to decide for/against","pattern":"sich entscheiden für + accusative OR gegen + accusative (to decide for/against)","explanation":"Sich entscheiden (reflexive, separable at für/gegen) = to decide, make a decision. Für = for: sich für etwas entscheiden (decide in favour of). Gegen = against: sich gegen etwas entscheiden (decide against). Ich habe mich für das Angebot entschieden = I decided on the offer. Die Entscheidung = the decision. Note: sich entschließen (zu + infinitive) = to decide to do (more of a resolution): Ich habe mich entschlossen, aufzuhören.","examples":[{"sentence":"Sie hat sich für eine Karriere in der Medizin entschieden.","translation":"She decided on a career in medicine."},{"sentence":"Er hat sich gegen das Projekt entschieden.","translation":"He decided against the project."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Erhältlich'' means?","options":["available","obtainable","accessible","purchasable"],"correctAnswer":"available"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"More and more people consciously decide in favour of a vegan diet.","options":["Immer mehr Menschen entscheiden sich bewusst für eine vegane Ernährung.","Vegane Ernährung wird beliebter.","Mehr Menschen essen vegan.","Immer mehr wählen vegan."],"correctAnswer":"Immer mehr Menschen entscheiden sich bewusst für eine vegane Ernährung."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Sie hat sich für eine Karriere in der Medizin ___.","options":["entschieden","entscheidend","entschließen","entschlossen"],"correctAnswer":"entschieden"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: He decided against the project","wordBankItems":["Er","hat","sich","gegen","das","Projekt","entschieden","."],"correctAnswer":"Er hat sich gegen das Projekt entschieden ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Bewusst'' when eating means?","options":["consciously/deliberately","healthily","carefully","mindfully"],"correctAnswer":"consciously/deliberately"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000013f',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss healthy city planning","Use Gesundheitsstadt vocabulary","Talk about urban health and wellbeing"],"explanation":{"intro":"Healthy city vocabulary covers urban planning for health, wellbeing, and livability.","culturalNote":"The WHO Healthy Cities network includes many German cities. Konzepte like 15-Minuten-Stadt (15-minute city) and Stadt der kurzen Wege (city of short distances) are being implemented. Lärm (noise), Luftverschmutzung (air pollution), and fehlende Grünflächen (lack of green spaces) are known urban health risks."},"examples":[{"german":"Die 15-Minuten-Stadt ist ein Modell, bei dem alle täglichen Bedürfnisse zu Fuß erreichbar sind.","english":"The 15-minute city is a model in which all daily needs are reachable on foot."},{"german":"Lärmschutzwände entlang von Autobahnen verbessern die Lebensqualität der Anwohner.","english":"Noise barriers along motorways improve the quality of life of residents."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss healthy city planning, urban wellbeing, and livability in German."}}',
'{"items":[{"word":"erreichbar","translation":"reachable/accessible","pronunciation":"er-RYK-bar","example":"Zu Fuß erreichbar."},{"word":"die Lärmschutzwand","translation":"noise barrier","pronunciation":"dee LÄRM-shoots-vant","example":"Lärmschutzwände bauen."},{"word":"der Anwohner","translation":"resident/local","pronunciation":"dayr AN-voh-ner","example":"Die Anwohner."},{"word":"die Lebensqualität","translation":"quality of life","pronunciation":"dee LAY-bens-kvah-lee-TÄT","example":"Lebensqualität verbessern."},{"word":"das Modell","translation":"model/concept","pronunciation":"dahs mo-DEL","example":"Ein nachhaltiges Modell."},{"word":"der Lärm","translation":"noise","pronunciation":"dayr lärm","example":"Lärm reduzieren."}]}',
'{"title":"Zu Fuß + erreichbar — on foot / reachable on foot","pattern":"zu Fuß (on foot) + erreichbar/gehen/kommen (to reach on foot)","explanation":"Zu Fuß = on foot (never ''mit Fuß'' or ''auf Fuß''). Zu Fuß gehen = to go on foot. Zu Fuß erreichbar = reachable on foot. Zu Fuß kommen = to come on foot. In the 15-minute city model, alles ist zu Fuß erreichbar = everything is reachable on foot. Compare: mit dem Rad (by bicycle), mit dem Bus (by bus), mit dem Auto (by car).","examples":[{"sentence":"Die Schule ist von hier aus zu Fuß erreichbar.","translation":"The school is reachable on foot from here."},{"sentence":"Ich gehe lieber zu Fuß, wenn das Wetter schön ist.","translation":"I prefer to go on foot when the weather is nice."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Anwohner'' means?","options":["resident/local","neighbour","inhabitant","local person"],"correctAnswer":"resident/local"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The 15-minute city is a model in which all daily needs are reachable on foot.","options":["Die 15-Minuten-Stadt ist ein Modell, bei dem alle täglichen Bedürfnisse zu Fuß erreichbar sind.","In der 15-Minuten-Stadt braucht man kein Auto.","Alles ist fußläufig erreichbar.","Das Stadtmodell ist nachhaltig."],"correctAnswer":"Die 15-Minuten-Stadt ist ein Modell, bei dem alle täglichen Bedürfnisse zu Fuß erreichbar sind."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Schule ist von hier aus zu Fuß ___.","options":["erreichbar","erreichend","zu erreichen","erreicht"],"correctAnswer":"erreichbar"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I prefer to go on foot when the weather is nice","wordBankItems":["Ich","gehe","lieber","zu","Fuß",",","wenn","das","Wetter","schön","ist","."],"correctAnswer":"Ich gehe lieber zu Fuß , wenn das Wetter schön ist ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Zu Fuß'' correctly goes with?","options":["gehen, kommen, erreichbar","fahren, reisen, kommen","laufen, reisen, nehmen","gehen, fahren, kommen"],"correctAnswer":"gehen, kommen, erreichbar"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000140',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss environmental awareness","Use Umweltbewusstsein vocabulary","Talk about environmental attitudes and behaviour"],"explanation":{"intro":"Environmental awareness vocabulary covers attitudes, behaviours, and values around environmental protection.","culturalNote":"Germany is often seen as a global leader in Umweltbewusstsein (environmental awareness). The Grünen (Green Party) has been influential in setting environmental norms. Concepts like Nachhaltigkeit (sustainability) and Verantwortung für die Natur (responsibility for nature) are mainstream. Fridays for Future has a strong German following."},"examples":[{"german":"Umweltbewusstsein beginnt im Alltag — beim Einkaufen, Fahren und Energieverbrauch.","english":"Environmental awareness starts in everyday life — in shopping, driving, and energy consumption."},{"german":"Die junge Generation ist umweltbewusster als frühere Generationen.","english":"The young generation is more environmentally aware than previous generations."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss environmental awareness, sustainability values, and eco-behaviour in German."}}',
'{"items":[{"word":"das Umweltbewusstsein","translation":"environmental awareness","pronunciation":"dahs oom-VELT-beh-voost-zyn","example":"Umweltbewusstsein fördern."},{"word":"umweltbewusst","translation":"environmentally aware/conscious","pronunciation":"oom-VELT-beh-voost","example":"Umweltbewusst handeln."},{"word":"der Energieverbrauch","translation":"energy consumption","pronunciation":"dayr eh-ner-GEE-fer-bro-kh","example":"Energieverbrauch senken."},{"word":"die Verantwortung","translation":"responsibility","pronunciation":"dee fer-ANT-vor-toong","example":"Verantwortung übernehmen."},{"word":"nachhaltiger Konsum","translation":"sustainable consumption","pronunciation":"NAKH-hal-tee-ger kon-ZOHM","example":"Nachhaltiger Konsum."},{"word":"der Fußabdruck","translation":"footprint","pronunciation":"dayr FOOS-ap-drook","example":"CO₂-Fußabdruck."}]}',
'{"title":"Im Alltag beginnen — to start in everyday life","pattern":"etwas beginnt im Alltag (something starts/begins in everyday life — small steps matter)","explanation":"Im Alltag = in everyday life, in daily life. Beginnen im Alltag = to start in everyday life (the key arena for behaviour change). Der Alltag (daily life/routine) is frequently used to emphasise that change doesn''t require grand gestures. Im Alltag umsetzen = to implement in everyday life. Der Alltag vs. das tägliche Leben — both refer to everyday life but Alltag has a slightly routine/mundane connotation.","examples":[{"sentence":"Klimaschutz beginnt im Alltag — mit kleinen Entscheidungen.","translation":"Climate protection begins in everyday life — with small decisions."},{"sentence":"Im Alltag kann jeder etwas beitragen.","translation":"In everyday life everyone can contribute something."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Fußabdruck'' in environmental context means?","options":["footprint","carbon footprint","ecological impact","environmental trace"],"correctAnswer":"footprint"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Environmental awareness starts in everyday life — in shopping, driving, and energy consumption.","options":["Umweltbewusstsein beginnt im Alltag — beim Einkaufen, Fahren und Energieverbrauch.","Umweltschutz ist wichtig.","Im Alltag kann man viel tun.","Energieverbrauch ist ein Thema."],"correctAnswer":"Umweltbewusstsein beginnt im Alltag — beim Einkaufen, Fahren und Energieverbrauch."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Klimaschutz beginnt im Alltag — mit kleinen ___.","options":["Entscheidungen","Entscheidung","Handlungen","Maßnahmen"],"correctAnswer":"Entscheidungen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: In everyday life everyone can contribute something","wordBankItems":["Im","Alltag","kann","jeder","etwas","beitragen","."],"correctAnswer":"Im Alltag kann jeder etwas beitragen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Verantwortung'' means?","options":["responsibility","duty","obligation","accountability"],"correctAnswer":"responsibility"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

